inline size_t operation_occurrences(std::span<const uint8_t> wire,const CapellaForkBlockRules& rules,const Bytes& operation,size_t field){
 require(wire.size()>=184,"operation block bound");const auto body=wire.subspan(184);const auto sync=(size_t(rules.transition.consensus.state.sync_committee_size)+7)/8+96;auto n=[&](size_t at){require(at<=body.size()&&4<=body.size()-at,"operation offset");size_t value=0;for(size_t k=0;k<4;++k)value|=size_t(body[at+k])<<(8*k);return value;};const auto start=n(200+field*4),end=field==4?n(220+sync):n(204+field*4);require(start<=end&&end<=body.size()&&(end-start)%operation.size()==0,"operation list shape");size_t count=0;for(size_t at=start;at<end;at+=operation.size())if(std::equal(operation.begin(),operation.end(),body.begin()+at))++count;return count;
}
